model_safe_stan:
// supervised naive Bayes

data {
  // training data
  int<lower=1> K; // num topics
  int<lower=1> V; // num words
  int<lower=0> M; // num docs
  int<lower=0> N; // total word instances
  array[M] int<lower=1, upper=K> z; // topic for doc m
  array[N] int<lower=1, upper=V> w; // word n
  array[N] int<lower=1, upper=M> doc; // doc ID for word n
  // hyperparameters
  vector<lower=0>[K] alpha; // topic prior
  vector<lower=0>[V] beta; // word prior
}
parameters {
  simplex[K] theta; // topic prevalence
  array[K] simplex[V] phi; // word dist for topic k
}
model {
  matrix[K, V] log_phi;
  matrix[N, K] topic_indicator;

  // priors
  theta ~ dirichlet(alpha);
  phi ~ dirichlet(beta);

  for (k in 1 : K) {
    for (v in 1 : V) {
      log_phi[k, v] = log(phi[k][v]);
    }
  }

  // likelihood for document topics
  z ~ categorical(theta);

  // likelihood for words, using one-hot document-topic indicators
  topic_indicator = rep_matrix(0, N, K);
  for (n in 1 : N) {
    topic_indicator[n, z[doc[n]]] = 1;
  }
  w ~ categorical_logit_glm(topic_indicator, rep_vector(0, V), log_phi);
}
